std::string transport_name(std::uint8_t ip_proto) {
	switch(ip_proto) {
	case 6: return "TCP";
	case 17: return "UDP";
	case 1: return "ICMP";
	case 58: return "ICMPv6";
	default: return "IP " + std::to_string(ip_proto);
	}
}

const char *delivery_name(const ip_addr &address) {
	if(stream_id::is_ipv4_broadcast(address)) return "broadcast";
	if(stream_id::is_multicast(address)) return "multicast";
	return "unicast";
}

} // namespace

flow::flow(const flow_id fid, std::string proto, std::string stream_key, std::string interface_name, event_sink &events)
	: m_fid(std::move(fid))
	, m_proto(std::move(proto))
	, m_stream_key(std::move(stream_key))
	, m_flow_key("if=" + std::to_string(m_fid.interface_id) +
	             tsv::key_suffix(m_fid.vlan) +
	             "|src=" + to_string(m_fid.src) +
	             "|dst=" + to_string(m_fid.dst))
	, m_src_text(to_string(m_fid.src))
	, m_dst_text(to_string(m_fid.dst))
	, m_interface_name(std::move(interface_name))
	, m_events(events) {
}

int flow::process(const info &i) {
	touch(i.time_epoch);
	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.lifetime.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count_total.inc();

	return 0;
}

void flow::emit_detected(double now) {
	m_events.emit(event_record{
		.time_epoch = now,
		.type = "flow_detected",
		.source = stream_json::make_flow_event_source(m_proto,
		                                             m_fid.interface_id,
		                                             m_interface_name,
		                                             m_stream_key,
		                                             m_flow_key,
		                                             m_fid.vlan),
		.detail = json{
			{"role", "flow"},
			{"endpoint", {
				{"src", m_src_text},
				{"dst", m_dst_text},
			}},
		},
	});
}

void flow::emit_lost(double now) {
	m_events.emit(event_record{
		.time_epoch = now,
		.type = "flow_lost",
		.source = stream_json::make_flow_event_source(m_proto,
		                                             m_fid.interface_id,
		                                             m_interface_name,
		                                             m_stream_key,
		                                             m_flow_key,
		                                             m_fid.vlan),
		.detail = json{
			{"role", "flow"},
			{"endpoint", {
				{"src", m_src_text},
				{"dst", m_dst_text},
			}},
			{"last_seen", last_seen()},
		},
	});
}

int flow::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;
	const auto bitrate = m.bitrate.snapshot_at(now);
	const auto packet_rate = m.packet_rate.snapshot_at(now);

	json j = stream_json::make_flow_metrics_base(m_proto,
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_stream_key,
	                                               m_flow_key,
	                                               m_fid.vlan);
	j["ip_proto"] = m_fid.ip_proto;
	j["role"] = "flow";
	j["endpoint"] = {
		{"src", m_src_text},
		{"dst", m_dst_text},
	};
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count_total.count()},
			{"total", m.packet_count_total.total()},
		}},
		{"duration", {
			{"seconds", m.lifetime.duration_sec()},
			{"first_seen", m.lifetime.first_seen()},
			{"last_seen", m.lifetime.last_seen()},
		}},
	});
	if(m_fid.vlan.empty()) {
		j.erase("vlan");
	}
	else {
		j["vlan"] = tsv::to_json(m_fid.vlan);
	}
	if (!bitrate.available) {
		for (const char *key : {"bps", "min", "max", "avg"}) {
			j["bitrate"][key] = nullptr;
		}
	}
	if (!packet_rate.available) {
		for (const char *key : {"pps", "min", "max", "avg"}) {
			j["packet_rate"][key] = nullptr;
		}
	}

	out.push_back(std::move(j));
	m_metrics_emitted = true;

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count_total.reset();

	return 0;
}

