		.time_epoch = now,
		.type = std::move(type),
		.source = m_event_source,
		.detail = std::move(detail),
	};
}

void stream::emit_detected(double now) {
	m_events.emit(make_event(now, "stream_detected", json{
		{"endpoint", {
			{"service", m_endpoint_text},
		}},
	}));

	trace(1, "other: stream detected service=%s", m_endpoint_text.c_str());
}

void stream::emit_lost(double now) {
	m_events.emit(make_event(now, "stream_lost", json{
		{"endpoint", {
			{"service", m_endpoint_text},
		}},
		{"last_seen", last_seen()},
		{"flow_count", m_flows.size()},
	}));

	trace(1, "other: stream lost service=%s", m_endpoint_text.c_str());
}

int stream::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.lifetime.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count_total.inc();

	flow_id fid = make_flow_id(i.interface_id,
	                           i.ip_proto,
	                           i.src.addr, i.src.port,
	                           i.dst.addr, i.dst.port,
	                           i.vlan);

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		auto created = std::make_unique<flow>(fid, m_sid.proto, m_stream_key, i.interface_name, m_events);
		it = m_flows.emplace(fid, std::move(created)).first;
		it->second->emit_detected(i.time_epoch);
	}

	return it->second->process(i);
}

int stream::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;
	const auto bitrate = m.bitrate.snapshot_at(now);
	const auto packet_rate = m.packet_rate.snapshot_at(now);

	json j = stream_json::make_stream_metrics_base(m_sid.proto,
	                                                 m_sid.interface_id,
	                                                 m_interface_name,
	                                                 m_stream_key,
	                                                 m_sid.vlan);
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count_total.count()},
			{"total", m.packet_count_total.total()},
		}},
		{"duration", {
			{"seconds", m.lifetime.duration_sec()},
			{"first_seen", m.lifetime.first_seen()},
			{"last_seen", m.lifetime.last_seen()},
		}},
	});

	if (!bitrate.available) {
		for (const char *key : {"bps", "min", "max", "avg"}) {
			j["bitrate"][key] = nullptr;
		}
	}
	if (!packet_rate.available) {
		for (const char *key : {"pps", "min", "max", "avg"}) {
			j["packet_rate"][key] = nullptr;
		}
	}

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count_total.reset();

	out.push_back(std::move(j));
	for(auto& [fid, flow] : m_flows) {
		flow->append_metrics(now, out);
	}

	return 0;
}

int stream::update_events(double now) {
	for(auto& [fid, flow] : m_flows) {
		flow->update_events(now);
	}
	return 0;
}

int stream::append_list(double now, json::array_t &out) {
	json::array_t flows = json::array();
	for(auto& [fid, flow] : m_flows) {
		flow->append_list(now, flows);
	}

	json stream_entry = stream_json::make_stream_list_base(m_sid.interface_id,
	                                                       m_interface_name,
	                                                       m_stream_key,
	                                                       m_sid.vlan);
	stream_entry["endpoint"] = {
		{"service", m_endpoint_text},
	};
	stream_entry["transport"] = transport_name(m_sid.ip_proto);
	stream_entry["delivery"] = delivery_name(m_sid.endpoint.addr);
	stream_entry["flows"] = std::move(flows);

	out.push_back(json{
		{"proto", m_sid.proto},
		{"stream", std::move(stream_entry)},
	});
	return 0;
}

void stream::expire_flows(double now, double flow_idle_sec) {
	for(auto it = m_flows.begin(); it != m_flows.end(); ) {
        if(it->second->metrics_emitted() &&
           it->second->expired(now, flow_idle_sec)) {
			it->second->emit_lost(now);
            it = m_flows.erase(it);
        }
        else {
            ++it;
        }
	}
}

streams::streams(config cfg, event_sink &events)
    : m_cfg(std::move(cfg))
    , m_events(events) {

}

flow_id streams::reverse_flow_id(const flow_id& fid) {
	return flow_id{
		.interface_id = fid.interface_id,
		.ip_proto = fid.ip_proto,
		.src = fid.dst,
		.dst = fid.src,
		.vlan = fid.vlan,
	};
}

bool streams::should_use_reverse_match(std::uint8_t ip_proto) {
	return ip_proto == 1 || ip_proto == 58;
}

int streams::process(tsv::ctx &c, const tsv::row_t &row) { return process(c, row, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids) { return process(c, row, target_ids, {}); }

int streams::process(tsv::ctx &c, const tsv::row_t &row, const std::vector<std::string> &target_ids, const std::string &stream_name) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}
	return process_info(std::move(i), target_ids, stream_name);
}

int streams::process_as(tsv::ctx &c, const tsv::row_t &row, std::string_view proto_override) {
	info i;
	if(parse_row(c, row, i) != 0) {
		return -1;
	}
	i.proto = std::string(proto_override);
	return process_info(std::move(i));
}

bool streams::reclassify_transport(const packet_context &packet,
                                   std::string_view to_proto,
                                   std::string_view tracking_key,
                                   std::string_view reason) {
	const auto same_transport = [&packet](const flow_id &fid) {
		return fid.interface_id == packet.interface_id &&
		       fid.ip_proto == packet.ip_proto &&
		       fid.vlan == packet.vlan &&
		       ((fid.src == packet.src && fid.dst == packet.dst) ||
		        (fid.src == packet.dst && fid.dst == packet.src));
	};
	json::array_t removed_flows;
	json::array_t removed_streams;

	// The same L4 flow can have separate provisional entries when tshark
	// changes its dissector label during a TLS handshake.  Do not rely on the
	// reverse index here: it intentionally stores only the newest entry.
	for(auto stream_it = m_streams.begin(); stream_it != m_streams.end(); ) {
		auto &stream = *stream_it->second;
		bool removed_from_stream = false;
		for(auto flow_it = stream.m_flows.begin(); flow_it != stream.m_flows.end(); ) {
			const auto &fid = flow_it->first;
			if(!same_transport(fid)) {
				++flow_it;
				continue;
			}

			json flow_source = stream.event_source();
			flow_source["flow_key"] = "if=" + std::to_string(fid.interface_id) +
				tsv::key_suffix(fid.vlan) + "|src=" + to_string(fid.src) + "|dst=" + to_string(fid.dst);
			removed_flows.push_back(json{
				{"source", std::move(flow_source)},
				{"detail", {
					{"role", "flow"},
					{"endpoint", {{"src", to_string(fid.src)}, {"dst", to_string(fid.dst)}}},
				}},
			});
			flow_it = stream.m_flows.erase(flow_it);
			removed_from_stream = true;
		}

		if(!removed_from_stream || !stream.empty()) {
			++stream_it;
			continue;
		}
		const auto sid = stream_it->first;
		removed_streams.push_back(json{
			{"source", stream.event_source()},
			{"detail", {{"endpoint", {{"service", to_string(sid.endpoint)}}}}},
		});
		m_monitoring_target_ids.erase(sid);
		m_stream_display_names.erase(sid);
		stream_it = m_streams.erase(stream_it);
	}

	for(auto it = m_reverse_stream_index.begin(); it != m_reverse_stream_index.end(); ) {
		if(same_transport(it->first)) it = m_reverse_stream_index.erase(it);
		else ++it;
	}

	if(removed_flows.empty()) {
		return false;
	}

	std::string endpoint_a = to_string(packet.src);
	std::string endpoint_b = to_string(packet.dst);
	if(endpoint_b < endpoint_a) std::swap(endpoint_a, endpoint_b);
	m_events.emit(event_record{
		.time_epoch = packet.time_epoch,
		.type = "transport_reclassified",
		.source = {
			{"type", "transport"},
			{"proto", transport_name(packet.ip_proto)},
			{"interface_id", packet.interface_id},
			{"connection_key", packet_connection_key(packet)},
			{"scope", tsv::scope_json(packet.interface_id, packet.interface_name, packet.vlan)},
		},
		.detail = {
			{"reason", std::string(reason)},
			{"from", {{"proto", transport_name(packet.ip_proto)}, {"flows", std::move(removed_flows)}, {"streams", std::move(removed_streams)}}},
			{"to", {{"proto", std::string(to_proto)}, {"tracking_key", std::string(tracking_key)}}},
			{"connection", {{"ip_proto", packet.ip_proto}, {"interface_id", packet.interface_id}, {"endpoint_a", endpoint_a}, {"endpoint_b", endpoint_b}}},
		},
	});
	trace(1, "other: transport reclassified from=%s to=%s connection=%s",
	      transport_name(packet.ip_proto).c_str(), std::string(to_proto).c_str(), packet_connection_key(packet).c_str());
	return true;
}

int streams::process_info(info i, const std::vector<std::string> &target_ids, const std::string &stream_name) {
    expire_streams(i.time_epoch);

	flow_id fid = make_flow_id(i.interface_id,
	                           i.ip_proto,
	                           i.src.addr, i.src.port,
	                           i.dst.addr, i.dst.port,
	                           i.vlan);

	stream_id sid = make_stream_id(i.interface_id,
	                               i.proto,
	                               i.ip_proto,
	                               i.src.addr, i.src.port,
	                               i.dst.addr, i.dst.port,
	                               i.vlan);

	if(should_use_reverse_match(i.ip_proto)) {
		auto reverse_it = m_reverse_stream_index.find(reverse_flow_id(fid));
		if(reverse_it != m_reverse_stream_index.end()) {
			sid = reverse_it->second;
		}
	}

	merge_monitoring_target_ids(m_monitoring_target_ids[sid], target_ids);
	if(!stream_name.empty()) {
		m_stream_display_names[sid] = stream_name;
		m_events.set_stream_display_name(make_stream_key(sid), stream_name);
	}

	auto it = m_streams.find(sid);
	if(it == m_streams.end()) {
		auto s = std::make_unique<stream>(sid, i.interface_name, m_events);
		s->emit_detected(i.time_epoch);
		int rc = s->process(i);
		m_streams.emplace(sid, std::move(s));
		m_reverse_stream_index[fid] = sid;
		return rc;
	}

	m_reverse_stream_index[fid] = sid;
	return it->second->process(i);
}

int streams::append_metrics(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_metrics(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::update_events(double now) {
	expire_streams(now);
	for(auto& [sid, stream] : m_streams) {
		stream->update_events(now);
	}
	return 0;
}

int streams::append_list(double now, json::array_t &out) {
	for(auto& [sid, stream] : m_streams) {
		const auto first = out.size();
		stream->append_list(now, out);
		append_monitoring_target_ids(out, first, m_monitoring_target_ids[sid]);
		append_stream_display_name(out, first, m_stream_display_names[sid]);
	}
	return 0;
}

int streams::parse_row(tsv::ctx &c, const tsv::row_t &row, info &i) {
	tsv::to_number(row[c.i.com.interface_id], i.interface_id);
	tsv::to_string(row[c.i.com.interface_name], i.interface_name);
	tsv::to_string(row[c.i.com.proto], i.proto);
	if(!parse_ip(tsv::field_or_empty(row, c.i.com.ip_src),
	             tsv::field_or_empty(row, c.i.com.ipv6_src),
	             i.src.addr)) {
		return -1;
	}
	if(!parse_ip(tsv::field_or_empty(row, c.i.com.ip_dst),
	             tsv::field_or_empty(row, c.i.com.ipv6_dst),
	             i.dst.addr)) {
		return -1;
	}
	if(!tsv::to_number(tsv::field_or_empty(row, c.i.com.udp_srcport), i.src.port)) {
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_srcport), i.src.port);
	}
	if(!tsv::to_number(tsv::field_or_empty(row, c.i.com.udp_dstport), i.dst.port)) {
		tsv::to_number(tsv::field_or_empty(row, c.i.com.tcp_dstport), i.dst.port);
	}
	tsv::to_number(i.src.addr.is_v6 ?
	               row[c.i.com.ipv6_nxt] : row[c.i.com.ip_proto], i.ip_proto);
	tsv::to_number(row[c.i.com.time_epoch], i.time_epoch);
	tsv::to_number(row[c.i.com.frame_len],  i.frame_len);
	i.vlan.id = std::string(tsv::field_or_empty(row, c.i.com.vlan_id));
	i.vlan.priority = std::string(tsv::field_or_empty(row, c.i.com.vlan_priority));
	i.vlan.dei = std::string(tsv::field_or_empty(row, c.i.com.vlan_dei));

	return 0;
}

void streams::expire_streams(double now) {
	for(auto it = m_streams.begin(); it != m_streams.end(); ) {
		it->second->expire_flows(now, m_cfg.timeout.flow_idle_sec);

		if(it->second->empty() &&
		    it->second->expired(now, m_cfg.timeout.stream_idle_sec)) {
			for(auto idx = m_reverse_stream_index.begin(); idx != m_reverse_stream_index.end(); ) {
				if(idx->second == it->first) {
					idx = m_reverse_stream_index.erase(idx);
				}
				else {
					++idx;
				}
			}
			it->second->emit_lost(now);
			m_monitoring_target_ids.erase(it->first);
			m_stream_display_names.erase(it->first);
			it = m_streams.erase(it);
		}
		else {
			++it;
		}
	}
}

