#include "packet_context.h"

#include <sstream>
#include <utility>

#include "tsv_util.h"

namespace {

bool read_packet_endpoint(const tsv::ctx &tc,
                          const tsv::row_t &row,
                          bool src,
                          ip_endpoint &out) {
	ip_addr addr{};
	const int ipv4_idx = src ? tc.i.com.ip_src : tc.i.com.ip_dst;
	const int ipv6_idx = src ? tc.i.com.ipv6_src : tc.i.com.ipv6_dst;
	if(!parse_ip(tsv::field_or_empty(row, ipv4_idx), tsv::field_or_empty(row, ipv6_idx), addr)) {
		return false;
	}

	std::uint32_t port32 = 0;
	const int udp_idx = src ? tc.i.com.udp_srcport : tc.i.com.udp_dstport;
	const int tcp_idx = src ? tc.i.com.tcp_srcport : tc.i.com.tcp_dstport;
	if(!tsv::to_number(tsv::field_or_empty(row, udp_idx), port32)) {
		port32 = 0;
		tsv::to_number(tsv::field_or_empty(row, tcp_idx), port32);
	}
	if(port32 > 65535U) {
		return false;
	}

	out = ip_endpoint{addr, static_cast<std::uint16_t>(port32)};
	return true;
}

bool packet_has_http_fields(const tsv::ctx &tc, const tsv::row_t &row) {
	return !tsv::field_or_empty(row, tc.i.http.method).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.uri).empty() ||
	       !tsv::field_or_empty(row, tc.i.http.status_code).empty();
}

std::string read_observed_host(const tsv::ctx &tc, const tsv::row_t &row) {
	const auto http_host = tsv::field_or_empty(row, tc.i.http.host);
	if(!http_host.empty()) {
		return std::string(http_host);
	}
	return std::string(tsv::field_or_empty(row, tc.i.tls.server_name));
}

std::string endpoint_key(const ip_endpoint &ep) {
	std::ostringstream oss;
	oss << to_string(ep.addr) << ':' << ep.port;
	return oss.str();
}

} // namespace

packet_context make_packet_context(tsv::ctx &tc, const tsv::row_t &row) {
	packet_context packet{};

	packet.proto = std::string(tsv::field_or_empty(row, tc.i.com.proto));
	packet.has_http_fields = packet_has_http_fields(tc, row);
	packet.dispatch_proto = packet.has_http_fields ? "HTTP" : packet.proto;

	tsv::to_number(tsv::field_or_empty(row, tc.i.com.time_epoch), tc.r.com.time_epoch);
	tsv::to_number(tsv::field_or_empty(row, tc.i.com.interface_id), tc.r.com.interface_id);
	tsv::to_string(tsv::field_or_empty(row, tc.i.com.interface_name), tc.r.com.interface_name);
	tc.r.com.vlan_id = std::string(tsv::field_or_empty(row, tc.i.com.vlan_id));
	tc.r.com.vlan_priority = std::string(tsv::field_or_empty(row, tc.i.com.vlan_priority));
	tc.r.com.vlan_dei = std::string(tsv::field_or_empty(row, tc.i.com.vlan_dei));

	packet.time_epoch = tc.r.com.time_epoch;
	packet.interface_id = tc.r.com.interface_id;
	packet.interface_name = tc.r.com.interface_name;
	packet.vlan = tsv::vlan_info{
		.id = tc.r.com.vlan_id,
		.priority = tc.r.com.vlan_priority,
		.dei = tc.r.com.vlan_dei,
	};

	read_packet_endpoint(tc, row, true, packet.src);
	read_packet_endpoint(tc, row, false, packet.dst);
	packet.host = read_observed_host(tc, row);
	packet.has_tcp_payload =
		tsv::to_number(tsv::field_or_empty(row, tc.i.com.tcp_len), packet.tcp_len) &&
		packet.tcp_len > 0;
	tsv::to_number(tsv::field_or_empty(row, packet.src.addr.is_v6 ? tc.i.com.ipv6_nxt : tc.i.com.ip_proto), packet.ip_proto);
	std::uint32_t tcp_fin = 0;
	packet.tcp_fin =
		tsv::to_number(tsv::field_or_empty(row, tc.i.com.tcp_flags_fin), tcp_fin) &&
		tcp_fin != 0;

	return packet;
}

std::string packet_connection_key(std::uint32_t interface_id,
                                  const tsv::vlan_info &vlan,
                                  const ip_endpoint &src,
                                  const ip_endpoint &dst) {
	std::string a = endpoint_key(src);
	std::string b = endpoint_key(dst);
	if(b < a) {
		std::swap(a, b);
	}

	std::ostringstream oss;
	oss << interface_id << tsv::key_suffix(vlan) << '|' << a << "<->" << b;
	return oss.str();
}

std::string packet_connection_key(const packet_context &packet) {
	return "ip=" + std::to_string(packet.ip_proto) + "|" +
		packet_connection_key(packet.interface_id, packet.vlan, packet.src, packet.dst);
}
#include "connection_tracker.h"

bool connection_tracker::known(const std::string &key) const {
	return find(key) != nullptr;
}

const connection_tracker::entry* connection_tracker::find(const std::string &key) const {
	const auto it = m_connections.find(key);
	if(it == m_connections.end()) {
		return nullptr;
	}
	return &it->second;
}

void connection_tracker::touch(std::string key, double now) {
	if(key.empty()) {
		return;
	}

	auto [it, inserted] = m_connections.emplace(std::move(key), entry{
		.first_seen = now,
		.last_seen = now,
		.flags = {},
	});
	if(!inserted) {
		it->second.last_seen = now;
	}
}

void connection_tracker::set_flag(const std::string &key, std::string flag) {
	if(key.empty()) {
		return;
	}

	auto it = m_connections.find(key);
	if(it == m_connections.end()) {
		return;
	}
	it->second.flags.insert(std::move(flag));
}

bool connection_tracker::has_flag(const std::string &key, const std::string &flag) const {
	const auto *entry = find(key);
	if(!entry) {
		return false;
	}
	return entry->flags.find(flag) != entry->flags.end();
}

void connection_tracker::prune(double now, double ttl_sec) {
	for(auto it = m_connections.begin(); it != m_connections.end(); ) {
		if((now - it->second.last_seen) >= ttl_sec) {
			it = m_connections.erase(it);
		}
		else {
			++it;
		}
	}
}

