#include "monitor.h"

#include <memory>
#include <utility>

#include "packet_context.h"
#include "batch_tshark_source.h"
#include "continuous_tshark_source.h"
#include "trace.h"
#include "tshark_command.h"
#include "tsv.h"
#include "tsv_util.h"



monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)),
	  m_reorder(m_cfg.reorder_holdback_sec) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}


	m_cfg.log.protocol_map_revision = m_protocol_map.revision();
	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_streams = std::make_unique<stream_registry>(m_protocol_map, m_logs->events());
	m_interfaces = std::make_unique<netif::interfaces>(netif::config{}, m_logs->events());

	const batch_tshark_source::config source_cfg{
		.input = m_cfg.input,
		.tshark = m_cfg.tshark,
		.decode_as = m_protocol_map.decode_as_rules(),
	};
	if(m_cfg.mode == config::processing_mode::continuous) {
		m_tsv_source = std::make_unique<continuous_tshark_source>(continuous_tshark_source::config{
			.input = source_cfg.input, .tshark = source_cfg.tshark, .decode_as = source_cfg.decode_as});
	}
	else {
		m_tsv_source = std::make_unique<batch_tshark_source>(source_cfg);
	}

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_tsv_source) {
		trace(0, "error: TSV source is not initialized");
		return 1;
	}
	m_second_boundary.reset();
	m_reorder.reset();
	m_reorder_tsv_ctx.reset();

	const int rc = m_tsv_source->run(*this);
	flush_reorder_all();
	return rc;
}

bool monitor::on_tsv_header(std::string_view header) {
	tsv::ctx tc;
	const std::string header_text{header};
	if(!tsv::init_ctx(tc, header_text)) {
		return false;
	}
	if(m_reorder_tsv_ctx && m_reorder_tsv_ctx->h != tc.h) {
		trace(0, "warn: tshark field layout changed; flushing the packet reorder buffer");
		flush_reorder_all();
	}
	m_reorder_tsv_ctx = std::move(tc);
	trace(7, "%.*s", static_cast<int>(header.size()), header.data());
	return true;
}

bool monitor::on_tsv_row(std::string_view row_text) {
	if(!m_reorder_tsv_ctx) {
		trace(0, "warn: TSV row received before header");
		return false;
	}
	trace(7, "%.*s", static_cast<int>(row_text.size()), row_text.data());
	std::string buffered_line{row_text};
	tsv::row_t row;
	tsv::split(buffered_line, row);
	double time_epoch = 0.0;
	tsv::to_number(row[m_reorder_tsv_ctx->i.com.time_epoch], time_epoch);
	m_reorder.push(time_epoch, std::move(buffered_line));
	flush_reorder_ready();
	return true;
}

void monitor::on_tsv_end() {
}

void monitor::flush_reorder_ready() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_ready([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

void monitor::flush_reorder_all() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_all([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	auto br = m_second_boundary.update(packet.time_epoch);
	if(!br.changed) {
		return 0;
	}

	write_second_boundary_outputs(tc.r.com.time_epoch, packet);

	return 0;
}

