int flow::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;
	const auto bitrate = m.bitrate.snapshot_at(now);
	const auto packet_rate = m.packet_rate.snapshot_at(now);

	json j = stream_json::make_flow_metrics_base(m_proto,
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_stream_key,
	                                               m_flow_key,
	                                               m_fid.vlan);
	j["ip_proto"] = m_fid.ip_proto;
	j["role"] = "flow";
	j["endpoint"] = {
		{"src", m_src_text},
		{"dst", m_dst_text},
	};
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count_total.count()},
			{"total", m.packet_count_total.total()},
		}},
		{"duration", {
			{"seconds", m.lifetime.duration_sec()},
			{"first_seen", m.lifetime.first_seen()},
			{"last_seen", m.lifetime.last_seen()},
		}},
	});
	if(m_fid.vlan.empty()) {
		j.erase("vlan");
	}
	else {
		j["vlan"] = tsv::to_json(m_fid.vlan);
	}
	if (!bitrate.available) {
		for (const char *key : {"bps", "min", "max", "avg"}) {
			j["bitrate"][key] = nullptr;
		}
	}
	if (!packet_rate.available) {
		for (const char *key : {"pps", "min", "max", "avg"}) {
			j["packet_rate"][key] = nullptr;
		}
	}

	out.push_back(std::move(j));
	m_metrics_emitted = true;

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count_total.reset();

	return 0;
}

