bool monitor::on_tsv_header(std::string_view header) {
	tsv::ctx tc;
	const std::string header_text{header};
	if(!tsv::init_ctx(tc, header_text)) {
		return false;
	}
	if(m_reorder_tsv_ctx && m_reorder_tsv_ctx->h != tc.h) {
		trace(0, "warn: tshark field layout changed; flushing the packet reorder buffer");
		flush_reorder_all();
	}
	m_reorder_tsv_ctx = std::move(tc);
	trace(7, "%.*s", static_cast<int>(header.size()), header.data());
	return true;
}

bool monitor::on_tsv_row(std::string_view row_text) {
	if(!m_reorder_tsv_ctx) {
		trace(0, "warn: TSV row received before header");
		return false;
	}
	trace(7, "%.*s", static_cast<int>(row_text.size()), row_text.data());
	std::string buffered_line{row_text};
	tsv::row_t row;
	tsv::split(buffered_line, row);
	double time_epoch = 0.0;
	tsv::to_number(row[m_reorder_tsv_ctx->i.com.time_epoch], time_epoch);
	m_reorder.push(time_epoch, std::move(buffered_line));
	flush_reorder_ready();
	return true;
}

void monitor::on_tsv_end() {
}

void monitor::flush_reorder_ready() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_ready([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

void monitor::flush_reorder_all() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_all([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	auto br = m_second_boundary.update(packet.time_epoch);
	if(!br.changed) {
		return 0;
	}

	write_second_boundary_outputs(tc.r.com.time_epoch, packet);

	return 0;
}

void monitor::update_second_boundary_state(double now) {
	m_interfaces->process(now);
	m_streams->update_events(now);
	m_interfaces->update_events(now);
}

json monitor::build_metrics_root(double now, const packet_context &packet) {
	json::array_t metrics_list;
	m_streams->append_metrics(now, metrics_list);

	json::array_t interface_metrics;
	m_interfaces->append_metrics(now, interface_metrics);

	json root{
		{"time", now},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
	};
	root["monitoring_groups"] = m_protocol_map.monitoring_group_health(root.at("metrics").get<json::array_t>());
	if(packet.vlan.empty() == false) {
		root["vlan"] = tsv::to_json(packet.vlan);
	}

	return root;
}

void monitor::evaluate_alerts(double now, const json &metrics_root) {
	if(!m_alerts || m_alerts->empty()) return;
	m_alerts->evaluate(now,
	                   metrics_root.at("metrics").get<json::array_t>(),
	                   metrics_root.at("interfaces").get<json::array_t>());
}

void monitor::write_second_boundary_outputs(double now, const packet_context &packet) {
	update_second_boundary_state(now);
	auto metrics_root = build_metrics_root(now, packet);
	evaluate_alerts(now, metrics_root);
	m_logs->append_metrics_snapshot(metrics_root);
}
