 71	int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
 72		std::vector<protocol_dispatch_decision> dispatch_decisions;
 73		dispatch_decisions.reserve(m_dispatch_adapters.size());
 74		bool adapter_observe_stream = false;
 75		bool adapter_suppress_other = false;
 76		for(auto &adapter : m_dispatch_adapters) {
 77			auto decision = adapter->prepare(packet);
 78			adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
 79			adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
 80			dispatch_decisions.emplace_back(std::move(decision));
 81		}
 82	
 83		bool dispatched_to_stream = false;
 84		const bool observe_stream =
 85			m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host, packet.interface_name) ||
 86			adapter_observe_stream;
 87		if(observe_stream) {
 88			if(auto *target = dispatch_target(packet.dispatch_proto)) {
 89				const auto target_ids = m_protocols.matching_target_ids(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host, packet.interface_name);
 90				target->process(tc, row, target_ids, m_protocols.stream_display_name(target_ids));
 91				dispatched_to_stream = true;
 92			}
 93			else if(!adapter_suppress_other) {
 94				m_other->process(tc, row);
 95			}
 96		}
 97	
 98		for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
 99			for(const auto &promotion : m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream)) {
100				m_other->reclassify_transport(packet, promotion.to_proto, promotion.tracking_key, promotion.reason);
101			}
102		}
103		for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
104			m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
105		}
106	
107		return 0;
108	}
