550	bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate) {
551		if(configured.addr == candidate.addr && configured.port == candidate.port) {
552			return true;
553		}
554	
555		if(!(upper(r.proto) == "RTP" && r.fec)) {
556			return false;
557		}
558		if(!(configured.addr == candidate.addr)) {
559			return false;
560		}
561		if(candidate.port < configured.port) {
562			return false;
563		}
564	
565		const auto offset = static_cast<unsigned>(candidate.port - configured.port);
566		return offset == 2U || offset == 4U;
567	}
