582	bool protocol_map::host_matches(const rule &r, std::string_view host) {
583		if(host.empty()) {
584			return false;
585		}
586	
587		const auto observed = lower_host(host);
588		if(observed.empty()) {
589			return false;
590		}
591	
592		for(const auto &configured_host : r.hosts) {
593			const auto configured = lower_host(configured_host);
594			if(configured.empty()) {
595				continue;
596			}
597			if(configured == observed) {
598				return true;
599			}
600			if(configured.size() > 2 && configured[0] == '*' && configured[1] == '.') {
601				const auto suffix = configured.substr(1);
602				if(observed.size() >= suffix.size() &&
603				   observed.compare(observed.size() - suffix.size(), suffix.size(), suffix) == 0) {
604					return true;
605				}
606			}
607		}
608	
609		return false;
610	}
