import { createHash } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type ProtocolRule = {
  id?: string;
  target_type?: "single" | "group";
  enabled?: boolean;
  observe?: boolean;
  proto: string;
  endpoints?: string | string[];
  hosts?: string | string[];
  domains?: string | string[];
  interfaces?: string | string[];
  decode_as?: string | string[];
  fec?: boolean;
  vlan?: number | string | null;
  stream_name?: string;
};

export type MonitoringTargetGroup = {
  id: string;
  kind: "bidirectional_pair" | "redundancy_set";
  name?: string;
  members: string[];
  paths?: Record<string, string>;
};

export type ProtocolMapDocument = {
  observe_mode?: "all" | "configured_only" | "configured_plus_other";
  protocols: ProtocolRule[];
  target_groups?: MonitoringTargetGroup[];
};

export type ProtocolMapResponse = {
  revision: string;
  path: string;
  document: ProtocolMapDocument;
  apply: "restart_required";
};

export class ProtocolMapConflictError extends Error {}
export class ProtocolMapValidationError extends Error {}

export class ProtocolMapSettings {
  constructor(private readonly stmConfigFile: string) {}

  async get(): Promise<ProtocolMapResponse> {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configuredPath = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? (stmConfig.configs as Record<string, unknown>).protocol_map : undefined;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new ProtocolMapValidationError("configs.protocol_map must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const mapFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const mapText = await readFile(mapFile, "utf8");
    const document = validateDocument(parseObject(mapText, "protocol map"));
    return { revision: revisionOf(stmConfigText, mapText), path: relativePath, document, apply: "restart_required" };
  }

  async update(input: { revision: unknown; path: unknown; document: unknown }): Promise<ProtocolMapResponse> {
    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new ProtocolMapConflictError("protocol map changed on the server; reload before applying");
    }
    const relativePath = validateRelativePath(input.path);
    const document = validateDocument(input.document);
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? { ...(stmConfig.configs as Record<string, unknown>) } : {};
    configs.protocol_map = relativePath;
    stmConfig.configs = configs;
    const mapFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    await atomicWrite(mapFile, `${JSON.stringify(document, null, 2)}\n`);
    await atomicWrite(this.stmConfigFile, `${JSON.stringify(stmConfig, null, 2)}\n`);
    return this.get();
  }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  try {
    const parsed = JSON.parse(text) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("must be an object");
    return parsed as Record<string, unknown>;
  } catch (error) {
    throw new ProtocolMapValidationError(`invalid ${label}: ${String(error)}`);
  }
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new ProtocolMapValidationError("protocol map path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new ProtocolMapValidationError("protocol map path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown): ProtocolMapDocument {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ProtocolMapValidationError("protocol map must be an object");
  const root = value as Record<string, unknown>;
  if (root.observe_mode !== undefined && !["all", "configured_only", "configured_plus_other"].includes(String(root.observe_mode))) {
    throw new ProtocolMapValidationError("invalid observe_mode");
  }
  if (!Array.isArray(root.protocols)) throw new ProtocolMapValidationError("protocols must be an array");
  const protocols = root.protocols.map((item, index) => validateRule(item, index));
  const targetIds = new Set<string>();
  for (const rule of protocols) {
    if (rule.id && targetIds.has(rule.id)) throw new ProtocolMapValidationError("Monitoring Target IDs must be unique: " + rule.id);
    if (rule.id) targetIds.add(rule.id);
  }
  const targetGroups = validateTargetGroups(root.target_groups, protocols);
  return {
    ...(root.observe_mode === undefined ? {} : { observe_mode: root.observe_mode as ProtocolMapDocument["observe_mode"] }),
    protocols,
    ...(root.target_groups === undefined ? {} : { target_groups: targetGroups })
  };
}

function validateRule(value: unknown, index: number): ProtocolRule {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ProtocolMapValidationError(`row ${index + 1} must be an object`);
  const rule = value as Record<string, unknown>;
  if (rule.id !== undefined && (typeof rule.id !== "string" || !isTargetId(rule.id))) throw new ProtocolMapValidationError("row " + (index + 1) + ": id must use letters, numbers, dot, underscore, or hyphen");
  if (rule.target_type !== undefined && rule.target_type !== "single" && rule.target_type !== "group") throw new ProtocolMapValidationError("row " + (index + 1) + ": target type must be single or group");
