550	bool alert_evaluator::matches_binding(const binding &b, const json &entry, bool is_interface) {
551		if(!b.monitoring_target_id.empty()) {
552			if(is_interface || !entry.contains("monitoring_target_ids") || !entry["monitoring_target_ids"].is_array()) return false;
553			return std::any_of(entry["monitoring_target_ids"].begin(), entry["monitoring_target_ids"].end(), [&b](const json &id) {
554				return id.is_string() && id.get<std::string>() == b.monitoring_target_id;
555			});
556		}
557		if(b.scope_target == "interface") return is_interface;
558		if(is_interface) return b.scope_target == "any";
559		if(b.scope_target == "flow" && !entry.contains("flow_key")) return false;
560		if(b.scope_target == "stream" && entry.contains("flow_key")) return false;
561		if(!b.scope_proto.empty() && json_string_or_empty(entry, "proto") != b.scope_proto) return false;
562		return true;
563	}
