565	bool alert_evaluator::matches_target(const rule &r, const json &entry, bool is_interface) {
566		if(r.target == "interface") {
567			return is_interface;
568		}
569		if(is_interface) {
570			return r.target == "any";
571		}
572		if(r.target == "flow" && !entry.contains("flow_key")) {
573			return false;
574		}
575		if(r.target == "stream" && entry.contains("flow_key")) {
576			return false;
577		}
578		if(!r.proto.empty()) {
579			const auto proto = json_string_or_empty(entry, "proto");
580			if(proto != r.proto) {
581				return false;
582			}
583		}
584		if(!r.flow_roles.empty()) {
585			const auto role = json_string_or_empty(entry, "role");
586			if(std::find(r.flow_roles.begin(), r.flow_roles.end(), role) == r.flow_roles.end()) {
587				return false;
588			}
589		}
590		if(!r.monitoring_target_id.empty()) {
591			if(!entry.contains("monitoring_target_ids") || !entry["monitoring_target_ids"].is_array()) {
592				return false;
593			}
594			const auto &target_ids = entry["monitoring_target_ids"];
595			if(std::none_of(target_ids.begin(), target_ids.end(), [&r](const json &id) {
596				return id.is_string() && id.get<std::string>() == r.monitoring_target_id;
597			})) {
598				return false;
599			}
600		}
601		return true;
602	}
