// The evaluator only needs an event sink that forwards records to consumers.
// Keep this test target independent of the journal and timeline writers.
void event_sink::add_consumer(event_consumer &consumer) {
	m_consumers.push_back(&consumer);
}

int event_sink::emit(const event_record &event) {
	int rc = 0;
	for(auto *consumer : m_consumers) {
		if(consumer == nullptr) continue;
		const auto current = consumer->handle_event(event);
		if(rc == 0 && current != 0) rc = current;
	}
	return rc;
}

namespace {

class collected_events final : public event_consumer {
public:
	int handle_event(const event_record &event) override {
		events.push_back(event);
		return 0;
	}

	std::vector<event_record> events;
};

json metric_entry(double bitrate) {
	return json{
		{"proto", "RTP"},
		{"flow_key", "RTP|test-flow"},
		{"role", "media"},
		{"bitrate", {{"bps", bitrate}}},
	};
}

} // namespace

int main() {
	const auto path = std::filesystem::temp_directory_path() / "stm-alert-evaluator-test.json";
	{
		std::ofstream out(path);
		out << R"({"policies":[],"bindings":[{"scope":{"kind":"protocol","proto":"RTP","target":"flow"},"mode":"individual","conditions":[{"id":"bitrate-high","target":"flow","proto":"RTP","metric":"bitrate.bps","type":"threshold","operator":">","error_threshold":100,"recover_threshold":100,"trigger_after_sec":1,"recover_after_sec":1}]}]})";
	}

	event_sink sink;
	collected_events collected;
	sink.add_consumer(collected);
	alert_evaluator evaluator(sink);
	assert(evaluator.load(path) == 0);

	// The second evaluation is 0.7ms short of one second and must remain
	// pending; the next sample confirms the Alert and preserves its start time.
	evaluator.evaluate(100.0007, {metric_entry(120)}, {});
	evaluator.evaluate(101.0000, {metric_entry(120)}, {});
	assert(collected.events.empty());
	evaluator.evaluate(102.0002, {metric_entry(120)}, {});
	assert(collected.events.size() == 1);
	assert(collected.events[0].type == "alert_detected");
	assert(std::abs(collected.events[0].detail.at("violation_started_at").get<double>() - 100.0007) < 0.000001);

	// Recovery has the same confirmation semantics and its own start time.
	evaluator.evaluate(103.0007, {metric_entry(80)}, {});
	evaluator.evaluate(104.0000, {metric_entry(80)}, {});
	assert(collected.events.size() == 1);
	evaluator.evaluate(105.0002, {metric_entry(80)}, {});
	assert(collected.events.size() == 2);
	assert(collected.events[1].type == "alert_recovered");
	assert(std::abs(collected.events[1].detail.at("recovery_started_at").get<double>() - 103.0007) < 0.000001);

	std::filesystem::remove(path);
	return 0;
}
