int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host, packet.interface_name) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			const auto target_ids = m_protocols.matching_target_ids(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host, packet.interface_name);
			target->process(tc, row, target_ids, m_protocols.stream_display_name(target_ids));
