}

protocol_dispatch_decision hls_dispatch_adapter::prepare(const packet_context &packet) {
	protocol_dispatch_decision out{};
	out.tracking_key = packet_connection_key(packet);
	out.matched =
		!packet.host.empty() &&
		m_protocols.should_observe("HTTP", packet.src, packet.dst, packet.vlan, packet.host, packet.interface_name);
	if(out.matched) {
		m_state.remember_candidate(out.tracking_key, packet.time_epoch);
	}

	out.tracked = m_state.known(out.tracking_key);
	out.observe_stream = packet.dispatch_proto == "HTTP" && out.tracked;
	// A host/SNI match is a candidate, not a confirmed HLS transport. Keep the
	// generic representation until HTTP processing confirms it, then promote it.
	out.suppress_other = m_state.detailed(out.tracking_key);
	return out;
}

std::vector<protocol_promotion> hls_dispatch_adapter::after_stream_dispatch(tsv::ctx &,
                                                                          const tsv::row_t &,
                                                                          const packet_context &packet,
                                                                          const protocol_dispatch_decision &decision,
                                                                          bool dispatched_to_stream) {
	if(!dispatched_to_stream || packet.dispatch_proto != "HTTP") {
		return {};
	}
	if(!decision.matched && !decision.tracked) {
		return {};
	}
	if(!m_state.remember_detailed(decision.tracking_key, packet.time_epoch)) {
		return {};
	}
	return {protocol_promotion{
		.tracking_key = decision.tracking_key,
		.from_proto = "TCP",
		.to_proto = "HLS",
		.reason = "specialized_protocol_confirmed",
	}};
}

void hls_dispatch_adapter::after_packet(tsv::ctx &tc,
                                        const tsv::row_t &row,
                                        const packet_context &packet,
                                        const protocol_dispatch_decision &decision) {
	if(packet.dispatch_proto == "HTTP" ||
	   (!packet.has_tcp_payload && !packet.tcp_fin) ||
	   !decision.tracked) {
		return;
	}

	trace(4, "monitor: tcp transport fallback to HLS proto=%s tcp_len=%u fin=%d src_port=%u dst_port=%u",
	      packet.proto.c_str(),
	      packet.tcp_len,
	      packet.tcp_fin ? 1 : 0,
	      static_cast<unsigned>(packet.src.port),
	      static_cast<unsigned>(packet.dst.port));
	m_hls.process(tc, row);
	if(m_state.tcp_fallback_ready(decision.tracking_key, packet.time_epoch)) {
		m_other.process_as(tc, row, hls_tcp_fallback_proto);
	}
}

void hls_dispatch_adapter::prune(double now) {
	m_state.prune(now);
}

